PROJECT_ID = "proj-router-001"
OTHER_PROJECT = "proj-other-999"


async def _seed_arch_run(db: AsyncSession, project_id: str = PROJECT_ID) -> Run:
    run = Run(
        id            = str(uuid.uuid4()),
        project_id    = project_id,
        workflow_type = "architecture",
        status        = "completed",
        input_data    = {},
        output_data   = {
            "tasks": [
                {
                    "title":        "Task A",
                    "description":  "Do A.",
                    "order_index":  0,
                    "pattern_refs": [],
                }
            ],
            "requirements": "Build stuff.",
        },
        run_metadata  = {},
        started_at    = datetime.now(timezone.utc),
        finished_at   = datetime.now(timezone.utc),
    )
    db.add(run)
    await db.flush()
    return run


async def _seed_codegen_run(
    db:          AsyncSession,
    *,
    project_id:  str  = PROJECT_ID,
    status:      str  = "completed",
    arch_run_id: str  = "arch-000",
    bundle_path: str | None = None,
    hitl_id:     str | None = None,
) -> Run:
    run = Run(
        id            = str(uuid.uuid4()),
        project_id    = project_id,
        workflow_type = "codegen",
        status        = status,
        input_data    = {
            "architecture_run_id": arch_run_id,
            "max_retries":         3,
        },
        output_data   = {
            "completed_task_ids": [],
            "failed_task_ids":    [],
            "bundle_path":        bundle_path,
            "hitl_request_id":    hitl_id,
        },
        run_metadata  = {"architecture_run_id": arch_run_id},
        started_at    = datetime.now(timezone.utc),
        finished_at   = datetime.now(timezone.utc) if status != "running" else None,
    )
    db.add(run)
    await db.flush()
    return run


async def _seed_tasks(
    db:     AsyncSession,
    run_id: str,
    count:  int = 2,
) -> list[Task]:
    tasks = []
    for i in range(count):
        t = Task(
            id              = str(uuid.uuid4()),
            run_id          = run_id,
            title           = f"Task {i}",
            description     = f"Do task {i}.",
            order_index     = i,
            pattern_refs    = [],
            status          = TaskStatus.COMPLETED.value,
            retry_count     = 0,
            generated_files = [f"src/task_{i}.py"],
        )
        db.add(t)
        tasks.append(t)
    await db.flush()
    return tasks


