    @pytest.mark.asyncio
    async def test_409_when_active_run_exists(self, client, db):
        """
        Active codegen run for the same architecture run → 409.
        """
        arch_run  = await _seed_arch_run(db)
        _         = await _seed_codegen_run(
            db,
            status      = "running",
            arch_run_id = arch_run.id,
        )

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs",
            json={"architecture_run_id": arch_run.id},
        )
        assert resp.status_code == 409
        assert "already active" in resp.json()["detail"].lower()

    @pytest.mark.asyncio
    async def test_422_on_missing_required_field(self, client):
        """
        Request body missing architecture_run_id → 422 Unprocessable Entity.
        """
        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs",
            json={"max_retries": 3},  # missing architecture_run_id
        )
        assert resp.status_code == 422

    @pytest.mark.asyncio
    async def test_max_retries_validated_range(self, client, db):
        """
        max_retries outside [1, 10] → 422.
        """
        arch_run = await _seed_arch_run(db)

        # Too low (ge=1 means 0 is invalid)
        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs",
            json={"architecture_run_id": arch_run.id, "max_retries": 0},
        )
        assert resp.status_code == 422

        # Too high (le=10 means 11 is invalid)
        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs",
            json={"architecture_run_id": arch_run.id, "max_retries": 11},
        )
        assert resp.status_code == 422

    @pytest.mark.asyncio
    async def test_completed_run_does_not_block_new_trigger(self, client, db):
        """
        A COMPLETED run for the same architecture run is not a conflict.
        409 only fires for active (running / paused_hitl) runs.
        """
        arch_run = await _seed_arch_run(db)
        _        = await _seed_codegen_run(
            db,
            status      = "completed",
            arch_run_id = arch_run.id,
        )

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs",
            json={"architecture_run_id": arch_run.id},
        )
        # 202 — completed run is not a conflict
        assert resp.status_code == 202


