class TestListRunsEndpoint:

    @pytest.mark.asyncio
    async def test_empty_list_when_no_runs(self, client):
        """
        No codegen runs seeded → response is an empty list, status 200.
        """
        resp = await client.get(f"/projects/{PROJECT_ID}/codegen/runs")
        assert resp.status_code == 200
        assert resp.json() == []

    @pytest.mark.asyncio
    async def test_returns_runs_in_descending_order(self, client, db):
        """
        Three runs seeded with different started_at timestamps.
        List returns them newest-first.
        """
        from datetime import timedelta

        base_time = datetime.now(timezone.utc)
        run_ids   = []

        for i in range(3):
            r = Run(
                id            = str(uuid.uuid4()),
                project_id    = PROJECT_ID,
                workflow_type = "codegen",
                status        = "completed",
                input_data    = {"architecture_run_id": f"arch-{i}"},
                output_data   = {},
                run_metadata  = {"architecture_run_id": f"arch-{i}"},
                started_at    = base_time + timedelta(minutes=i),
                finished_at   = base_time + timedelta(minutes=i, seconds=30),
            )
            db.add(r)
            run_ids.append(r.id)

        await db.flush()

        resp = await client.get(f"/projects/{PROJECT_ID}/codegen/runs")
        assert resp.status_code == 200

        returned_ids = [item["run_id"] for item in resp.json()]
        # Newest first — run_ids[2] should appear before run_ids[0]
        assert returned_ids.index(run_ids[2]) < returned_ids.index(run_ids[0])

