    async def test_tasks_ordered_by_order_index(self, client, db):
        """
        Tasks in the detail response are sorted by order_index ascending.
        """
        run = await _seed_codegen_run(db)

        for i in reversed(range(4)):    # seed in reverse order
            db.add(Task(
                id              = str(uuid.uuid4()),
                run_id          = run.id,
                title           = f"Task {i}",
                description     = "",
                order_index     = i,
                pattern_refs    = [],
                status          = TaskStatus.COMPLETED.value,
                retry_count     = 0,
                generated_files = [],
            ))

        await db.flush()

        resp   = await client.get(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}"
        )
        indices = [t["order_index"] for t in resp.json()["tasks"]]
        assert indices == sorted(indices)


