class TestApproveEndpoint:

    @pytest.mark.asyncio
    async def test_200_on_valid_approval(self, client, db, mock_resume):
        """
        Approving a paused_hitl run returns 200 with ApproveCodegenResponse.
        """
        run = await _seed_codegen_run(db, status="paused_hitl", hitl_id="hitl-001")

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/approve",
            json={"approved": True},
        )

        assert resp.status_code == 200
        body = resp.json()
        assert body["run_id"]  == run.id
        assert "status"  in body
        assert "message" in body

    @pytest.mark.asyncio
    async def test_200_on_valid_rejection_with_feedback(self, client, db, mock_resume):
        """
        Rejecting with a feedback string returns 200.
        """
        mock_resume.return_value = {
            "run_id":  "run-mocked-001",
            "status":  "failed",
            "message": "Rejected.",
        }

        run = await _seed_codegen_run(db, status="paused_hitl", hitl_id="hitl-002")

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/approve",
            json={"approved": False, "feedback": "Quality below threshold."},
        )

        assert resp.status_code == 200
        assert resp.json()["status"] == "failed"

    @pytest.mark.asyncio
    async def test_resume_called_with_correct_args(self, client, db, mock_resume):
        """
        resume_codegen_run is called with the correct run_id, project_id,
        approved, and feedback values.
        """
        run = await _seed_codegen_run(db, status="paused_hitl", hitl_id="hitl-003")

        await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/approve",
            json={"approved": True},
        )

        mock_resume.assert_called_once_with(
            run_id     = run.id,
            project_id = PROJECT_ID,
            approved   = True,
            feedback   = None,
        )

    @pytest.mark.asyncio
    async def test_400_when_run_not_paused_hitl(self, client, db):
        """
        Approving a run that is not paused_hitl returns 400.
        """
        run = await _seed_codegen_run(db, status="completed")

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/approve",
            json={"approved": True},
        )

        assert resp.status_code == 400
        assert "paused" in resp.json()["detail"].lower()

    @pytest.mark.asyncio
    async def test_400_when_rejecting_without_feedback(self, client, db):
        """
        approved=False without feedback string returns 400.
        Feedback is required on rejection.
        """
        run = await _seed_codegen_run(db, status="paused_hitl", hitl_id="hitl-004")

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/approve",
            json={"approved": False},
        )

        assert resp.status_code == 400
        assert "feedback" in resp.json()["detail"].lower()

    @pytest.mark.asyncio
    async def test_404_when_run_not_found(self, client):
        """
        Approving a non-existent run_id returns 404.
        """
        resp = await client.post(
            "/projects/proj-router-001/codegen/runs/nonexistent/approve",
            json={"approved": True},
        )
        assert resp.status_code == 404

    @pytest.mark.asyncio
    async def test_404_when_run_belongs_to_other_project(self, client, db):
        """
        Run exists but under OTHER_PROJECT — returns 404.
        """
        run = await _seed_codegen_run(
            db,
            project_id = OTHER_PROJECT,
            status     = "paused_hitl",
            hitl_id    = "hitl-x",
        )

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/approve",
            json={"approved": True},
        )
        assert resp.status_code == 404

    @pytest.mark.asyncio
    async def test_422_on_missing_approved_field(self, client, db):
        """
        Request body missing 'approved' field returns 422.
        """
        run = await _seed_codegen_run(db, status="paused_hitl", hitl_id="hitl-005")

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/approve",
            json={"feedback": "some comment"},  # missing 'approved'
        )
        assert resp.status_code == 422

    @pytest.mark.asyncio
    async def test_resume_runner_error_returns_500(self, client, db, mock_resume):
        """
        If resume_codegen_run raises an unexpected exception,
        the endpoint returns 500 — not a silent pass.
        """
        mock_resume.side_effect = RuntimeError("DB connection lost.")

        run = await _seed_codegen_run(db, status="paused_hitl", hitl_id="hitl-006")

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/approve",
            json={"approved": True},
        )
        assert resp.status_code == 500

    @pytest.mark.asyncio
    async def test_running_run_cannot_be_approved(self, client, db):
        """
        Status=running is not paused_hitl → 400.
        Approval is only valid for runs awaiting the HITL decision.
        """
        run = await _seed_codegen_run(db, status="running")

        resp = await client.post(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/approve",
            json={"approved": True},
        )
        assert resp.status_code == 400


