# GET /runs/{run_id}/bundle/download
# ===========================================================================

class TestDownloadBundleEndpoint:

    @pytest.mark.asyncio
    async def test_200_streams_zip_file(self, client, db):
        """
        Run with a real bundle_path pointing to a valid ZIP on disk.
        Endpoint returns 200 with content-type application/zip.
        """
        # Create a real temporary ZIP so FileResponse can serve it
        with tempfile.NamedTemporaryFile(
            suffix=".zip", delete=False
        ) as tmp:
            tmp_path = tmp.name

        with zipfile.ZipFile(tmp_path, "w") as zf:
            zf.writestr("src/main.py", "print('hello')")

        try:
            run = await _seed_codegen_run(
                db,
                status      = "paused_hitl",
                bundle_path = tmp_path,
            )

            resp = await client.get(
                f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/bundle/download"
            )

            assert resp.status_code == 200
            assert resp.headers["content-type"] == "application/zip"
            assert len(resp.content) > 0
        finally:
            os.unlink(tmp_path)

    @pytest.mark.asyncio
    async def test_400_when_bundle_not_yet_available(self, client, db):
        """
        Run exists but output_data has no bundle_path → 400.
        Bundle not yet available message in response.
        """
        run = await _seed_codegen_run(
            db,
            status      = "running",
            bundle_path = None,
        )

        resp = await client.get(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/bundle/download"
        )

        assert resp.status_code == 400
        assert "bundle" in resp.json()["detail"].lower()

    @pytest.mark.asyncio
    async def test_404_when_bundle_file_missing_from_disk(self, client, db):
        """
        bundle_path set in output_data but the file no longer exists on disk.
        Returns 404 — file may have been cleaned up.
        """
        run = await _seed_codegen_run(
            db,
            status      = "paused_hitl",
            bundle_path = "/tmp/this_bundle_does_not_exist_12345.zip",
        )

        resp = await client.get(
            f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/bundle/download"
        )

        assert resp.status_code == 404
        assert "not found on disk" in resp.json()["detail"].lower()

    @pytest.mark.asyncio
    async def test_404_when_run_not_found(self, client):
        """
        Non-existent run_id returns 404 for bundle download.
        """
        resp = await client.get(
            f"/projects/{PROJECT_ID}/codegen/runs/nonexistent/bundle/download"
        )
        assert resp.status_code == 404

    @pytest.mark.asyncio
    async def test_404_when_run_belongs_to_other_project(self, client, db):
        """
        Run exists under OTHER_PROJECT.
        Download request from PROJECT_ID returns 404.
        """
        with tempfile.NamedTemporaryFile(suffix=".zip", delete=False) as tmp:
            tmp_path = tmp.name

        with zipfile.ZipFile(tmp_path, "w") as zf:
            zf.writestr("src/a.py", "pass")

        try:
            run = await _seed_codegen_run(
                db,
                project_id  = OTHER_PROJECT,
                status      = "paused_hitl",
                bundle_path = tmp_path,
            )

            resp = await client.get(
                f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/bundle/download"
            )
            assert resp.status_code == 404
        finally:
            os.unlink(tmp_path)

    @pytest.mark.asyncio
    async def test_download_filename_contains_run_id_prefix(self, client, db):
        """
        Content-Disposition header includes the first 8 chars of run_id
        so downloaded files are self-identifying.
        """
        with tempfile.NamedTemporaryFile(suffix=".zip", delete=False) as tmp:
            tmp_path = tmp.name

        with zipfile.ZipFile(tmp_path, "w") as zf:
            zf.writestr("src/b.py", "pass")

        try:
            run = await _seed_codegen_run(
                db,
                status      = "paused_hitl",
                bundle_path = tmp_path,
            )

            resp = await client.get(
                f"/projects/{PROJECT_ID}/codegen/runs/{run.id}/bundle/download"
            )
            disposition = resp.headers.get("content-disposition", "")
            assert run.id[:8] in disposition
        finally:
            os.unlink(tmp_path)


