# AUTH ENFORCEMENT
# ===========================================================================

class TestAuthEnforcement:
    """
    Verify that removing the auth override causes 401/403 responses.
    These tests temporarily clear the dependency overrides so the real
    auth middleware runs.
    """

    @pytest.mark.asyncio
    async def test_trigger_requires_auth(self, db):
        """
        No auth override → real get_current_user runs → 401 when no token.
        """
        _clear_overrides()

        from app.storage.database import get_async_db

        async def _override_db():
            yield db

        app.dependency_overrides[get_async_db] = _override_db

        async with AsyncClient(
            transport = ASGITransport(app=app),
            base_url  = "http://test",
        ) as ac:
            resp = await ac.post(
                f"/projects/{PROJECT_ID}/codegen/runs",
                json={"architecture_run_id": "arch-001"},
            )

        _clear_overrides()
        assert resp.status_code in (401, 403)

    @pytest.mark.asyncio
    async def test_list_runs_requires_auth(self, db):
        """GET /runs without auth returns 401/403."""
        _clear_overrides()

        from app.storage.database import get_async_db

        async def _override_db():
            yield db

        app.dependency_overrides[get_async_db] = _override_db

        async with AsyncClient(
            transport = ASGITransport(app=app),
            base_url  = "http://test",
        ) as ac:
            resp = await ac.get(f"/projects/{PROJECT_ID}/codegen/runs")

        _clear_overrides()
        assert resp.status_code in (401, 403)
